INSERT INTO `articles` (`id`, `payload`, `category`, `updated_at`) VALUES
('art-1', '{\"id\": \"art-1\", \"slug\": \"۱۰-راهکار-علمی-و-کاربردی-برای-غلبه-بر-اضطراب-روزمره\", \"tags\": [\"اضطراب\", \"CBT\", \"آرامش\"], \"title\": \"۱۰ راهکار علمی و کاربردی برای غلبه بر اضطراب روزمره\", \"views\": 1240, \"status\": \"published\", \"content\": \"\\n# ۱۰ راهکار علمی و کاربردی برای غلبه بر اضطراب روزمره\\n\\nاضطراب یکی از شایع‌ترین واکنش‌های طبیعی بدن به فشارهای روانی است. اما زمانی که مداوم و بی‌دلیل تجربه شود، می‌تواند سلامت جسمی و روانی شما را به خطر اندازد.\\n\\n## ۱. تکنیک تنفس مربع (Box Breathing)\\nتنفس عمیق کنترل‌شده فوراً سیستم عصب پاراسمپاتیک شما را فعال کرده و ضربان قلب را پایین می‌آورد.\\n- ۴ ثانیه دم\\n- ۴ ثانیه نگه‌داشتن نفس\\n- ۴ ثانیه بازدم\\n- ۴ ثانیه مکث\\n\\n## ۲. بازنویسی افکار کارآمد (CBT)\\nبه جای تسلیم شدن در برابر سناریوهای فاجعه‌ساز، از خود بپرسید: \\\"واقع‌بینانه‌ترین احتمالی که ممکن است رخ دهد چیست؟\\\"\\n\\n## ۳. کاهش مصرف کافئین\\nکافئین موجود در قهوه و نوشابه‌های انرژی‌زا علائم جسمی اضطراب مانند تپش قلب و لرزش دست را تشدید می‌کند.\\n    \", \"summary\": \"اضطراب مزمن انرژی ذهنی ما را تحلیل می‌برد. در این مقاله تکنیک‌های استاندارد CBT و تنفس دیافراگمی را مرور می‌کنیم.\", \"authorId\": \"dr-deihimi\", \"category\": \"سلامت روان و اضطراب\", \"readTime\": \"۶ دقیقه\", \"authorName\": \"خانم مرجانه دیهیمی\", \"categoryId\": \"acat-سلامت-روان-و-اضطراب\", \"coverImage\": \"https://lh3.googleusercontent.com/aida-public/AB6AXuDe1dXMDn_23JKLDcC4xG7u5z2K-9e7BHx1iv3F0_ob1YhOh2KRT6i-PXvtaDylIthNtv8Db9wWCPhT7yLE3Qv7RQFmwmf2PV-4Wb1KHsNII3cQDWJQy9EKs5e3buxSGu0u4SG6cru9e84OwKkH4A34wIgkAbsI38hfbv3_fr4-k1sQ2ImRGPfgAchK-Wp3P2Ram9pJGlY_Po_lnTaAJQqrRdQeb4mTwMc_f5WTBskLWmXrJFooydAWM6t7rbksIk12MZrah430t5s\", \"pageBuilder\": {\"blocks\": [{\"id\": \"richText-mryy8uqe-51y7zk\", \"type\": \"richText\", \"props\": {\"html\": \"<p># ۱۰ راهکار علمی و کاربردی برای غلبه بر اضطراب روزمره</p>\\n<p>اضطراب یکی از شایع‌ترین واکنش‌های طبیعی بدن به فشارهای روانی است. اما زمانی که مداوم و بی‌دلیل تجربه شود، می‌تواند سلامت جسمی و روانی شما را به خطر اندازد.</p>\\n<p>## ۱. تکنیک تنفس مربع (Box Breathing)<br/>تنفس عمیق کنترل‌شده فوراً سیستم عصب پاراسمپاتیک شما را فعال کرده و ضربان قلب را پایین می‌آورد.<br/>- ۴ ثانیه دم<br/>- ۴ ثانیه نگه‌داشتن نفس<br/>- ۴ ثانیه بازدم<br/>- ۴ ثانیه مکث</p>\\n<p>## ۲. بازنویسی افکار کارآمد (CBT)<br/>به جای تسلیم شدن در برابر سناریوهای فاجعه‌ساز، از خود بپرسید: \\\"واقع‌بینانه‌ترین احتمالی که ممکن است رخ دهد چیست؟\\\"</p>\\n<p>## ۳. کاهش مصرف کافئین<br/>کافئین موجود در قهوه و نوشابه‌های انرژی‌زا علائم جسمی اضطراب مانند تپش قلب و لرزش دست را تشدید می‌کند.</p>\"}}], \"version\": 1}, \"publishedAt\": \"۱۴۰۳/۰۴/۲۰\", \"authorAvatar\": \"/staff/dr-deihimi.jpg\"}', 'سلامت روان و اضطراب', '2026-07-24 14:08:38'),
('art-2', '{\"id\": \"art-2\", \"slug\": \"play-therapy-child-anxiety\", \"tags\": [\"بازی درمانی\", \"فرزندپروری\", \"کودک\"], \"title\": \"نقش بازی‌درمانی در درمان اضطراب جدایی کودکان\", \"views\": 890, \"status\": \"published\", \"content\": \"\\n# نقش بازی‌درمانی در درمان اضطراب جدایی کودکان\\n\\nاضطراب جدایی یکی از شایع‌ترین دغدغه‌های والدین هنگام ورود کودک به مهدکودک یا مدرسه است.\\n\\n## چرا بازی‌درمانی پاسخ می‌دهد؟\\nبازی زبان طبیعی کودک است. درمانگر از طریق عروسک‌ها، میز شن و وسایل نقاشی، فضای امنی ایجاد می‌کند تا کودک ترس رها شدن را تخلیه کند.\\n\\n## توصیه‌هایی به والدین\\n- هرگز بدون خداحافظی کودک را ترک نکنید.\\n- زمان دقیق بازگشت خود را به زبان ساده مشخص کنید (مثلاً: \\\"بعد از زنگ ناهار برمی‌گردم\\\").\\n    \", \"summary\": \"کودکان احساسات و ترس‌های خود را در قالب کلمات بیان نمی‌کنند، بلکه بازی زبان اصلی آن‌ها برای ابراز اضطراب است.\", \"authorId\": \"dr-nejad-hosseini\", \"category\": \"کودک و نوجوان\", \"readTime\": \"۵ دقیقه\", \"authorName\": \"خانم سعیده نژاد حسینی\", \"categoryId\": \"acat-کودک-و-نوجوان\", \"coverImage\": \"https://lh3.googleusercontent.com/aida-public/AB6AXuDx3suYmpRCaVgqWnDmPXOSHhEBJ_RuL9btSXxCZbcu_EwlxOrb8Os_2BskOcr7Sdccu0eucS1FU8jqmUrDVp3H-qq2ng_f_SF8FGxqN2TjcN-Kz2CSdueM9bHrp15cRrqy3w7yPg7s3v-UY5ZlfyUNOo0Y2ag-FJXSFo7_PtGQBf7cYnGQBwxFGgnPY0Ag5dAXyAL2hJPuqmtT06L-lZ9fWS12FPUdFfBJaUziyucwXmHRevYzr2Ry6pNyNSR88USQb6Mf32ymDI0\", \"publishedAt\": \"۱۴۰۳/۰۴/۱۵\", \"authorAvatar\": \"/staff/dr-nejad-hosseini.jpg\"}', 'کودک و نوجوان', '2026-07-24 11:57:53'),
('art-3', '{\"id\": \"art-3\", \"slug\": \"gottman-marriage-communication\", \"tags\": [\"زوج درمانی\", \"گاتمن\", \"صمیمیت\"], \"title\": \"اصول گفتگو بدون گارد در روابط زناشویی (متد گاتمن)\", \"views\": 1560, \"status\": \"published\", \"content\": \"\\n# اصول گفتگو بدون گارد در روابط زناشویی\\n\\nجان گاتمن پس از ۴۰ سال پژوهش روی هزاران زوج، به این نتیجه رسید که نحوه مدیریت اختلافات تعیین‌کننده دوام رابطه است.\\n\\n## ۴ رفتار خطرناک در گفتگو:\\n۱. **انتقاد شخصیتی:** به جای حمله به شخصیت (\\\"تو همیشه بی‌مسئولیتی!\\\")، احساس خود را مطرح کنید (\\\"من وقتی قرار را فراموش می‌کنی دلگیر می‌شوم\\\").\\n۲. **تحقیر:** استفاده از تمسخر و زبان بدن توهین‌آمیز.\\n۳. **حالت دفاعی:** شانه خالی کردن از مسئولیت.\\n۴. **دیوارکشی:** سکوت و ترک گفتگو.\\n    \", \"summary\": \"بررسی ۴ سوار سرنوشت‌ساز لغو صمیمیت (انتقاد، تحقیر، حالت دفاعی و دیوارکشی) و جایگزین‌های سالم آن‌ها.\", \"authorId\": \"dr-ghadyani\", \"category\": \"ازدواج و زوجین\", \"readTime\": \"۸ دقیقه\", \"authorName\": \"خانم مرجان قدیانی\", \"categoryId\": \"acat-ازدواج-و-زوجین\", \"coverImage\": \"https://lh3.googleusercontent.com/aida-public/AB6AXuBeSLgnKpImcpOx-GjmdRz2jCdvrXg6C6uHwVHr4M_Ou_BFEaJZX5Gwe5l20NVDRIXkXKXZpMigdwIEZN0gOgr5afflN1SUkWS89CUBs3BkGq1U56b7gWlcn6j2Z5hK97D84ix0u2m-rPBD6rDEAn4M7qTn7DfoqpluLJyEJ7xZV75b53RPCHOKzoQOYqS8XiPWkR_OLqqjJKsDM5ko7z5lo3OE4NsDZ4KZsxeFDqOjdbAN3MaPjgryoF3pPubvy6xqyD2bKNCvSEk\", \"publishedAt\": \"۱۴۰۳/۰۴/۱۰\", \"authorAvatar\": \"/staff/dr-ghadyani.jpg\"}', 'ازدواج و زوجین', '2026-07-24 11:57:53');

