INSERT INTO `doctors` (`id`, `payload`, `updated_at`) VALUES
('dr-afshar', '{\"id\": \"dr-afshar\", \"bio\": \"ارزیاب رسمی هوش و استعداد درخشان، تست‌های تخصصی شخصیت‌شناسی (MMPI, NEO) و اختلالات یادگیری.\", \"name\": \"خانم زهره افشار\", \"tags\": [\"تست هوش\", \"شخصیت‌شناسی\"], \"title\": \"متخصص روان‌سنجی\", \"active\": true, \"avatar\": \"/staff/dr-afshar.jpg\", \"degree\": \"دکتری تخصصی سنجش و اندازه‌گیری\", \"gender\": \"female\", \"specialties\": [\"assessment\"], \"sessionTypes\": [\"in-person\"], \"experienceYears\": 11}', '2026-07-24 09:20:26'),
('dr-deihimi', '{\"id\": \"dr-deihimi\", \"bio\": \"با بیش از ۱۲ سال سابقه تخصصی در درمان اضطراب، افسردگی و وسواس فکری-عملی با رویکرد CBT و طرحواره درمانی. مدرس کارگاه‌های بین‌المللی روانشناسی.\", \"name\": \"خانم مرجانه دیهیمی\", \"tags\": [\"درمان فردی\", \"اضطراب\", \"CBT\"], \"title\": \"روانشناس و درمانگر ارشد\", \"active\": true, \"avatar\": \"/staff/dr-deihimi.jpg\", \"degree\": \"کارشناسی ارشد روانشناسی بالینی\", \"gender\": \"female\", \"specialties\": [\"cbt\", \"individual\"], \"sessionTypes\": [\"in-person\", \"online\"], \"experienceYears\": 12}', '2026-07-24 09:20:26'),
('dr-ghadyani', '{\"id\": \"dr-ghadyani\", \"bio\": \"متخصص زوج‌درمانی و مشاوره پیش از ازدواج بر اساس پروتکل استاندارد گاتمن. همراه بیش از ۵۰۰ زوج در مسیر صمیمیت و حل تعارضات.\", \"name\": \"خانم مرجان قدیانی\", \"tags\": [\"زوج درمانی\", \"مشاوره پیش از ازدواج\"], \"title\": \"مشاور خانواده و ازدواج\", \"active\": true, \"avatar\": \"/staff/dr-ghadyani.jpg\", \"degree\": \"دکتری تخصصی مشاوره خانواده\", \"gender\": \"female\", \"specialties\": [\"family\"], \"sessionTypes\": [\"in-person\", \"online\"], \"experienceYears\": 10}', '2026-07-24 09:20:26'),
('dr-homayounian', '{\"id\": \"dr-homayounian\", \"bio\": \"هدایت شغلی، برنامه‌ریزی کنکور و تحصیلات عالی، استعدادیابی متناسب با تیپ شخصیتی و کوچینگ عملکرد.\", \"name\": \"خانم بدرالسادات همایونیان\", \"tags\": [\"استعدادیابی\", \"برنامه‌ریزی\"], \"title\": \"مشاور ارشد تحصیلی و شغلی\", \"active\": true, \"avatar\": \"/staff/dr-homayounian.jpg\", \"degree\": \"کارشناسی ارشد مشاوره شغلی\", \"gender\": \"female\", \"specialties\": [\"career\"], \"sessionTypes\": [\"in-person\", \"online\"], \"experienceYears\": 13}', '2026-07-24 09:20:26'),
('dr-jalali', '{\"id\": \"dr-jalali\", \"bio\": \"ابراز هیجانات و بهبود خودشناسی از طریق هنردرمانی، نقاشی‌درمانی و تکنیک‌های روان‌شناختی خلاقانه.\", \"name\": \"بی نظیر جلالی\", \"tags\": [\"هنر درمانی\", \"خودشناسی\"], \"title\": \"روانشناس و هنر درمانگر\", \"active\": true, \"avatar\": \"/staff/dr-jalali.jpg\", \"degree\": \"کارشناسی ارشد روانشناسی\", \"gender\": \"female\", \"specialties\": [\"individual\"], \"sessionTypes\": [\"in-person\", \"online\"], \"experienceYears\": 7}', '2026-07-24 09:20:26'),
('dr-molazem', '{\"id\": \"dr-molazem\", \"bio\": \"درمان تخصصی OCD و وسواس‌های عملی فکری با متد مواجهه و جلوگیری از پاسخ (ERP) و رویکرد پذیرش و تعهد (ACT).\", \"name\": \"خانم اعظم ملازم\", \"tags\": [\"ACT\", \"ERP\"], \"title\": \"درمانگر حیطه وسواس\", \"active\": true, \"avatar\": \"/staff/dr-molazem.jpg\", \"degree\": \"کارشناسی ارشد روانشناسی بالینی\", \"gender\": \"female\", \"specialties\": [\"cbt\", \"individual\"], \"sessionTypes\": [\"in-person\", \"online\"], \"experienceYears\": 10}', '2026-07-24 09:20:26'),
('dr-nejad-hosseini', '{\"id\": \"dr-nejad-hosseini\", \"bio\": \"متخصص بازی‌درمانی و درمان اختلالات رفتاری، اضطراب جدایی و اضطراب اجتماعی کودکان. مدرس دوره‌های تخصصی فرزندپروری.\", \"name\": \"خانم سعیده نژاد حسینی\", \"tags\": [\"فرزندپروری\", \"بازی درمانی\"], \"title\": \"روانشناس کودک و نوجوان\", \"active\": true, \"avatar\": \"/staff/dr-nejad-hosseini.jpg\", \"degree\": \"کارشناسی ارشد روانشناسی کودک\", \"gender\": \"female\", \"specialties\": [\"child\"], \"sessionTypes\": [\"in-person\", \"online\"], \"experienceYears\": 9}', '2026-07-24 09:20:26'),
('dr-sajedi', '{\"id\": \"dr-sajedi\", \"bio\": \"تمرکز بر روانکاوی و درمان تحلیلی، سوگ، تروماهای کودکی و چالش‌های عمیق هویتی.\", \"name\": \"خانم تینا ساجدی\", \"tags\": [\"روانکاوی\", \"درمان سوگ\"], \"title\": \"روان‌درمانگر تحلیلی\", \"active\": true, \"avatar\": \"/staff/dr-sajedi.jpg\", \"degree\": \"کارشناسی ارشد روانشناسی بالینی\", \"gender\": \"female\", \"specialties\": [\"individual\"], \"sessionTypes\": [\"in-person\", \"online\"], \"experienceYears\": 8}', '2026-07-24 09:20:26'),
('dr-shaghaghi', '{\"id\": \"dr-shaghaghi\", \"bio\": \"درمانگر تخصصی اختلالات خلق‌وخو، افسردگی مقاوم به درمان و حملات پانیک با رویکرد CBT و مایندفولنس.\", \"name\": \"خانم پروانه شقاقی\", \"tags\": [\"افسردگی\", \"اختلالات خلقی\"], \"title\": \"روانشناس بالینی\", \"active\": true, \"avatar\": \"/staff/dr-shaghaghi.jpg\", \"degree\": \"دکتری روانشناسی بالینی\", \"gender\": \"female\", \"specialties\": [\"cbt\", \"individual\"], \"sessionTypes\": [\"in-person\", \"online\"], \"experienceYears\": 14}', '2026-07-24 09:20:26');

