INSERT INTO `faqs` (`id`, `payload`, `updated_at`) VALUES
('faq-1', '{\"id\": \"faq-1\", \"date\": \"۱۴۰۳/۰۴/۱۸\", \"answer\": \"روانپزشک پزشک متخصص است که می‌تواند دارودرمانی انجام دهد. روانشناس (درمانگر) از روش‌های روان‌درمانی مانند شناختی-رفتاری (CBT) یا طرحواره درمانی استفاده می‌کند. در جلسات اولیه روانشناسی ارزیابی می‌شوید و در صورت نیاز شدید به دارو، به روانپزشک ارجاع داده خواهید شد.\", \"status\": \"approved\", \"askedBy\": \"مریم ک.\", \"category\": \"adult\", \"question\": \"تفاوت روانشناس و روانپزشک چیست و برای افسردگی به کدام مراجعه کنم؟\", \"likesCount\": 24, \"serviceTitle\": \"مشاوره فردی و درمان افسردگی\", \"responderName\": \"دکتر مرجانه دیهیمی\"}', '2026-07-24 09:20:26'),
('faq-2', '{\"id\": \"faq-2\", \"date\": \"۱۴۰۳/۰۴/۱۵\", \"answer\": \"مدت زمان استاندارد هر جلسه مشاوره فردی ۴۵ الی ۵۰ دقیقه است. تعداد جلسات بسته به نوع مسئله، شدت اضطراب یا طرحواره‌ها متغیر است، اما معمولاً پروژه‌های درمان شناختی رفتاری بین ۸ تا ۱۶ جلسه به طول می‌انجامند.\", \"status\": \"approved\", \"askedBy\": \"امیرحسین ر.\", \"category\": \"adult\", \"question\": \"هر جلسه مشاوره فردی چقدر زمان می‌برد و چند جلسه نیاز است؟\", \"likesCount\": 18, \"serviceTitle\": \"درمان اضطراب و وسواس\", \"responderName\": \"دکتر مرجانه دیهیمی\"}', '2026-07-24 09:20:26'),
('faq-3', '{\"id\": \"faq-3\", \"date\": \"۱۴۰۳/۰۴/۲۰\", \"answer\": \"بازی درمانی تخصصی معمولاً از سن ۳ سالگی به بالا کاربرد دارد. برای کودکان زیر ۳ سال، جلسات مشاوره فرزندپروری و آموزش والدگری با حضور والدین انجام می‌شود.\", \"status\": \"approved\", \"askedBy\": \"زهرا م. (والد)\", \"category\": \"child\", \"question\": \"از چه سنی می‌توان کودک را برای بازی‌درمانی و سنجش به کلینیک آورد؟\", \"likesCount\": 31, \"serviceTitle\": \"بازی درمانی و اضطراب کودک\", \"responderName\": \"خانم سعیده نژاد حسینی\"}', '2026-07-24 09:20:26'),
('faq-4', '{\"id\": \"faq-4\", \"date\": \"۱۴۰۳/۰۴/۱۲\", \"answer\": \"تشخیص بیش‌فعالی بر اساس مصاحبه بالینی استاندارد، تست‌های روانسنجی توجه و تمرکز (مانند IVA) و در صورت لزوم نقشه مغزی (QEEG) انجام می‌گیرد تا نوع دقیق نقص توجه مشخص شود.\", \"status\": \"approved\", \"askedBy\": \"علی رضایی\", \"category\": \"child\", \"question\": \"آیا برای تشخیص بیش‌فعالی کودک تست یا نقشه مغزی لازم است؟\", \"likesCount\": 15, \"serviceTitle\": \"اختلال بیش‌فعالی (ADHD)\", \"responderName\": \"خانم سعیده نژاد حسینی\"}', '2026-07-24 09:20:26'),
('faq-5', '{\"id\": \"faq-5\", \"date\": \"۱۴۰۳/۰۴/۲۲\", \"answer\": \"بله، برای زوج‌درمانی کارآمد حضور هر دو طرف ضروری است. البته ممکن است درمانگر در روند درمان، جلسات انفرادی تک‌نفره نیز برای هر یک از زوجین تنظیم کند.\", \"status\": \"approved\", \"askedBy\": \"سامان و نیلوفر\", \"category\": \"marriage\", \"question\": \"آیا در جلسات زوج‌درمانی حضور هر دو نفر الزامی است؟\", \"likesCount\": 42, \"serviceTitle\": \"زوج درمانی و مشاوره پیش از ازدواج\", \"responderName\": \"خانم مرجان قدیانی\"}', '2026-07-24 09:20:26'),
('faq-6', '{\"id\": \"faq-6\", \"date\": \"۱۴۰۳/۰۴/۱۰\", \"answer\": \"تست‌های روانسنجی معتبر (مانند NEO و انریچ) ابزار کالیبره‌شده‌ای برای شناخت تفاوت‌های شخصیتی، ارزش‌ها و حل تعارضات هستند. این تست‌ها در کنار مصاحبه تخصصی بالینی شفافیت بالایی ایجاد می‌کنند.\", \"status\": \"approved\", \"askedBy\": \"رضا ف.\", \"category\": \"marriage\", \"question\": \"تست‌های مشاوره قبل از ازدواج چقدر صحت در پیش‌بینی موفقیت رابطه دارند؟\", \"likesCount\": 29, \"serviceTitle\": \"مشاوره پیش از ازدواج\", \"responderName\": \"خانم مرجان قدیانی\"}', '2026-07-24 09:20:26'),
('faq-7', '{\"id\": \"faq-7\", \"date\": \"۱۴۰۳/۰۴/۰۵\", \"answer\": \"نوروفیدبک یک روش کاملاً غیرتهاجمی و یادگیری سلول‌های مغزی است و هیچ‌گونه عوارض دارویی ندارد. اثرات آن پس از تکمیل دوره درمانی (معمولاً ۲۰ تا ۳۰ جلسه) ماندگار و تثبیت‌شده خواهد بود.\", \"status\": \"approved\", \"askedBy\": \"محسن ک.\", \"category\": \"neurofeed\", \"question\": \"آیا جلسات نوروفیدبک عوارض جانبی دارند و اثر آن چقدر ماندگار است؟\", \"likesCount\": 37, \"serviceTitle\": \"نوروفیدبک و لورتا\", \"responderName\": \"دکتر مرجانه دیهیمی\"}', '2026-07-24 09:20:26'),
('faq-8', '{\"id\": \"faq-8\", \"date\": \"۱۴۰۳/۰۴/۰۱\", \"answer\": \"پژوهش‌های متعدد نشان داده که جلسات آنلاین (به‌ویژه مشاوره فردی و روان‌درمانی شناختی) کیفیتی کاملاً برابر با جلسات حضوری دارند. این جلسات در بستر امن و اختصاصی برگزار می‌شوند.\", \"status\": \"approved\", \"askedBy\": \"سارا از آلمان\", \"category\": \"online\", \"question\": \"کیفیت و اثربخشی جلسات آنلاین نسبت به حضوری چگونه است؟\", \"likesCount\": 19, \"serviceTitle\": \"مشاوره تصویری و آنلاین\", \"responderName\": \"دکتر مرجانه دیهیمی\"}', '2026-07-24 09:20:26'),
('faq-9', '{\"id\": \"faq-9\", \"date\": \"۱۴۰۳/۰۳/۲۵\", \"answer\": \"مراجعه‌کنندگان محترم می‌توانند تا ۲۴ ساعت قبل از زمان تعیین‌شده، بدون جریمه نوبت خود را تغییر داده یا جابه‌جا کنند. لغو در کمتر از ۲۴ ساعت مشمول کسر درصدی از کنسلی خواهد بود.\", \"status\": \"approved\", \"askedBy\": \"پشتیبانی کلینیک\", \"category\": \"general\", \"question\": \"شرایط کنسلی یا تغییر زمان نوبت در کلینیک ژینو چگونه است؟\", \"likesCount\": 50, \"serviceTitle\": \"نوبت‌دهی و قوانین لغو\", \"responderName\": \"مدیریت کلینیک ژینو\"}', '2026-07-24 09:20:26');

