INSERT INTO `pages` (`id`, `payload`, `updated_at`) VALUES
('about', '{\"id\": \"about\", \"slug\": \"/about\", \"title\": \"درباره ما\", \"pageBuilder\": {\"blocks\": [{\"id\": \"pageHero-mrysfiqa-9naddc\", \"type\": \"pageHero\", \"props\": {\"badge\": \"درباره کلینیک روانشناسی ژینو\", \"title\": \"پناهگاهی امن برای آرامش و تعادل روان شما\", \"subtitle\": \"کلینیک ژینو با داشتن مجوز رسمی از سازمان نظام روانشناسی و مشاوره جمهوری اسلامی ایران و بهره‌گیری از کادری علمی و دلسوز، همراه همیشگی شماست.\", \"showBooking\": true, \"primaryCtaLabel\": \"رزرو نوبت\"}}, {\"id\": \"richText-mrysfiqa-b9sl7t\", \"type\": \"richText\", \"props\": {\"html\": \"<h2>داستان شکل‌گیری ژینو</h2>\\n<p>نام «ژینو» در لغت به معنای «تولد دوباره و حیات‌بخش» است. مجموعه ژینو فعالیت خود را در سال ۱۳۹۲ با هدف ایجاد تحولی بنیادین در نحوه ارائه خدمات روانشناسی شروع کرد. ما باور داریم روان‌درمانی یک درمان کلیشه‌ای نیست، بلکه فرآیندی کاملاً انسانی و مبتنی بر همدلی آگاهانه است.</p>\\n<p><strong>چشم‌انداز:</strong> ارتقای فرهنگ مراجعه به روانشناس، حذف تابوهای سلامت روان در جامعه و ارائه استانداردهای درمانی برابر با کلینیک‌های پیشرو جهان.</p>\"}}, {\"id\": \"features-mrysfiqa-w7xz40\", \"type\": \"features\", \"props\": {\"items\": [{\"desc\": \"تمامی مباحث مطرح‌شده در جلسات کاملاً محرمانه باقی می‌مانند.\", \"icon\": \"lock\", \"title\": \"رازداری و اصول اخلاقی\"}, {\"desc\": \"درمانگران همواره در دوره‌های بین‌المللی و بازآموزی دانشگاهی حضور دارند.\", \"icon\": \"biotech\", \"title\": \"کیفیت و دانش روزآمد\"}, {\"desc\": \"پذیرش نامشروط هر مراجع در محیطی لبریز از احترام و کرامت انسانی.\", \"icon\": \"handshake\", \"title\": \"احترام و بدون قضاوت\"}], \"title\": \"ارزش‌های بنیادین کلینیک ژینو\"}}, {\"id\": \"cta-mrysfiqa-7z3acy\", \"type\": \"cta\", \"props\": {\"badge\": \"آشنایی بیشتر\", \"title\": \"آماده‌اید مسیر درمان را آغاز کنید؟\", \"subtitle\": \"تیم پذیرش ژینو آماده راهنمایی شماست.\", \"phoneHref\": \"tel:02188776655\", \"phoneLabel\": \"تماس (۰۲۱-۸۸۷۷۶۶۵۵)\"}}], \"version\": 1}}', '2026-07-24 10:18:56'),
('blog', '{\"id\": \"blog\", \"slug\": \"/blog\", \"title\": \"مقالات\", \"pageBuilder\": {\"blocks\": [{\"id\": \"pageHero-mrysfiqa-69qx2n\", \"type\": \"pageHero\", \"props\": {\"badge\": \"مجله تخصصی روانشناسی ژینو\", \"title\": \"مقالات، آموزه‌ها و تازه‌های سلامت روان\", \"subtitle\": \"جدیدترین پژوهش‌ها و راهکارهای علمی متخصصان کلینیک ژینو در زمینه اضطراب، روابط عاطفی، تربیت و خودشناسی.\", \"showBooking\": false}}, {\"id\": \"articlesGrid-mrysfiqa-894jx1\", \"type\": \"articlesGrid\", \"props\": {\"title\": \"آخرین مقالات\", \"showSearch\": true, \"showCategories\": true}}], \"version\": 1}}', '2026-07-24 10:18:56'),
('contact', '{\"id\": \"contact\", \"slug\": \"/contact\", \"title\": \"تماس با ما\", \"pageBuilder\": {\"blocks\": [{\"id\": \"pageHero-mrysfiqa-b2wrta\", \"type\": \"pageHero\", \"props\": {\"badge\": \"ارتباط با مرکز ژینو\", \"title\": \"تماس با ما و آدرس کلینیک\", \"subtitle\": \"همکاران ما در بخش پذیرش آماده پاسخگویی به سوالات و راهنمایی شما جهت ثبت نوبت مشاوره می‌باشند.\", \"showBooking\": true, \"primaryCtaLabel\": \"رزرو آنلاین نوبت\"}}, {\"id\": \"contactCards-mrysfiqa-oue2pm\", \"type\": \"contactCards\", \"props\": {\"email\": \"info@zhinoclinic.ir\", \"hours\": \"شنبه تا چهارشنبه ۹ الی ۲۰ | پنجشنبه ۹ الی ۱۶\", \"phone1\": \"۰۲۱-۸۸۷۷۶۶۵۵\", \"phone2\": \"۰۲۱-۸۸۷۷۴۴۳۳\", \"address\": \"تهران، خیابان ولیعصر، بالاتر از میدان ونک، کوچه نگار، ساختمان پزشکان، طبقه ۴\", \"addressNote\": \"دسترسی آسان از میدان ونک\"}}, {\"id\": \"contactForm-mrysfiqa-wts0nn\", \"type\": \"contactForm\", \"props\": {\"title\": \"ارسال پیام به پذیرش\", \"subtitle\": \"پیام شما در کوتاه‌ترین زمان بررسی می‌شود.\"}}], \"version\": 1}}', '2026-07-24 10:18:56'),
('home', '{\"id\": \"home\", \"slug\": \"/\", \"title\": \"صفحه خانه\", \"status\": \"published\", \"excerpt\": \"\", \"updatedAt\": \"2026-07-24T15:54:58.035Z\", \"coverImage\": \"\", \"layoutWidth\": \"contained\", \"pageBuilder\": {\"blocks\": [{\"id\": \"heroHeader-mrz01hek-nwr4so\", \"type\": \"heroHeader\", \"props\": {\"badge\": \"مرکز روان‌درمانی و مشاوره ژینو\", \"stats\": [{\"icon\": \"verified\", \"label\": \"جلسه موفق درمانی\", \"value\": \"+۱۲,۰۰۰\"}, {\"icon\": \"sentiment_satisfied\", \"label\": \"رضایت مراجعین\", \"value\": \"۹۸.۴٪\"}, {\"icon\": \"groups\", \"label\": \"روانشناس و درمانگر ارشد\", \"value\": \"+۱۵\"}], \"title\": \"پناهگاهی برای یافتن آرامش و تعادل روان\", \"slides\": [{\"badge\": \"اتاق مشاوره\", \"image\": \"https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&q=80&w=1200\", \"title\": \"اتاق تخصصی مشاوره و روان‌درمانی\", \"rating\": \"۴.۹ از ۵.۰\", \"description\": \"فضای آرام با نور طبیعی، مبلمان ارگونومیک و حریم خصوصی کامل\", \"floatingIcon\": \"calendar_month\", \"floatingBadge\": \"نوبت‌دهی آنلاین ۲۴/۷\"}, {\"badge\": \"جلسه درمانی\", \"image\": \"https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?auto=format&fit=crop&q=80&w=1200\", \"title\": \"فضای امن برای گفت‌وگو و درمان\", \"rating\": \"۴.۸ از ۵.۰\", \"description\": \"طراحی‌شده برای جلسات فردی، زوج و خانواده با استانداردهای حرفه‌ای\", \"floatingIcon\": \"event_available\", \"floatingBadge\": \"رزرو حضوری و آنلاین\"}], \"ctaIcon\": \"psychology\", \"ctaLink\": \"\", \"showCta\": true, \"ctaLabel\": \"راهنمای آنلاین انتخاب درمانگر\", \"subtitle\": \"با بهره‌گیری از متدهای علمی روز دنیا شامل CBT، طرحواره درمانی و نوروفیدبک لورتا، مسیر درمان اختصاصی شما را طراحی می‌کنیم.\", \"ctaAction\": \"guide\", \"mediaSide\": \"end\", \"showStats\": true, \"titleSize\": \"lg\", \"ctaVariant\": \"outline\", \"showStatus\": true, \"statusText\": \"پذیرش فعال\", \"accentColor\": \"primary\", \"departments\": [{\"icon\": \"person\", \"label\": \"مشاوره فردی بزرگسال\"}, {\"icon\": \"toys\", \"label\": \"بازی درمانی کودک\"}, {\"icon\": \"favorite\", \"label\": \"مشاوره ازدواج\"}, {\"icon\": \"neurology\", \"label\": \"نوروفیدبک\"}], \"mediaRadius\": 20, \"contentAlign\": \"start\", \"showCarousel\": true, \"sectionPadding\": \"md\", \"titleHighlight\": \"آرامش و تعادل روان\", \"showDepartments\": true, \"showRatingBadge\": true, \"carouselAutoplay\": true, \"departmentsTitle\": \"دپارتمان‌های فعال برای دریافت خدمت فوری:\", \"showCarouselDots\": true, \"showFloatingBadge\": true, \"carouselIntervalMs\": 5000, \"showCarouselArrows\": true}}, {\"id\": \"servicesGrid-mrysfiqa-ujrbs8\", \"type\": \"servicesGrid\", \"props\": {\"title\": \"دپارتمان‌ها و خدمات کلینیک\", \"subtitle\": \"انتخاب خدمت مناسب، اولین گام مسیر درمان است\"}}, {\"id\": \"staffCarousel-mrz0xrh4-z6qh8q\", \"type\": \"staffCarousel\", \"props\": {\"badge\": \"کادر درمانی و روانشناسان کلینیک ژینو\", \"title\": \"متخصصین برجسته ما\", \"autoplay\": false, \"maxCount\": 0, \"showDots\": true, \"subtitle\": \"همراهان مجرب و تخصصی شما در مسیر بهبودی و خودشناسی\", \"intervalMs\": 5000, \"onlyActive\": true, \"showArrows\": true, \"showViewAll\": true, \"bookingLabel\": \"رزرو نوبت\", \"profileLabel\": \"پروفایل درمانگر\", \"viewAllLabel\": \"مشاهده همه\", \"columnsMobile\": 1, \"columnsTablet\": 2, \"columnsDesktop\": 4, \"specialtiesFilter\": []}}, {\"id\": \"cta-mrysfiqa-bqp3bb\", \"type\": \"cta\", \"props\": {\"badge\": \"گام اول به سوی سلامت روان\", \"title\": \"همین امروز نوبت مشاوره خود را رزرو کنید\", \"subtitle\": \"فرآیند رزرو نوبت کمتر از ۲ دقیقه زمان می‌برد.\", \"phoneHref\": \"tel:02188776655\", \"phoneLabel\": \"تماس با پذیرش (۰۲۱-۸۸۷۷۶۶۵۵)\"}}, {\"id\": \"articlesGrid-mrz0x4pa-mbfuzt\", \"type\": \"articlesGrid\", \"props\": {\"title\": \"آخرین مقالات\", \"showSearch\": false, \"columnCount\": 3, \"showExcerpt\": false, \"columnsDesktop\": 3, \"showCategories\": false, \"showCategoryBadge\": true}}], \"version\": 1}}', '2026-07-24 15:54:58');

