('academic-career', '{\"id\": \"academic-career\", \"icon\": \"work\", \"title\": \"تحصیلی و شغلی\", \"bgClass\": \"bg-surface-container-high\", \"description\": \"استعدادیابی تخصصی، برنامه‌ریزی تحصیلی و هدایت مسیر شغلی متناسب با ویژگی‌های شخصیتی و توانمندی‌ها.\", \"pageBuilder\": {\"blocks\": [{\"id\": \"hero-mryr2rs0-carvo8\", \"type\": \"hero\", \"props\": {\"badge\": \"استعدادیابی و هدایت شغلی علمی\", \"title\": \"مشاوره تحصیلی، هدایت شغلی و کنکور\", \"format\": \"حضوری و آنلاین\", \"duration\": \"۴۵ الی ۶۰ دقیقه\", \"subtitle\": \"کشف استعدادیابی ذاتی، برنامه‌ریزی تخصصی تحصیلی، انتخاب رشته هوشمندانه و موفقیت در مسیر شغلی\", \"heroImage\": \"https://images.unsplash.com/photo-1522202176988-66273c2fd55f?auto=format&fit=crop&q=80&w=1000\", \"sessionFeeNote\": \"شامل آزمون‌های جامع رغبت‌سنجی و شخصیت شغلی\", \"satisfactionRate\": \"۹۹٪ قبولی و موفقیت برنامه‌ای\"}}, {\"id\": \"highlights-mryr2rs0-zkoogu\", \"type\": \"highlights\", \"props\": {\"items\": [{\"icon\": \"school\", \"label\": \"برنامه‌ریزی کنکور\", \"value\": \"شخصی‌سازی شده\"}, {\"icon\": \"work_history\", \"label\": \"تست‌های شغلی\", \"value\": \"MBTI & Holland\"}, {\"icon\": \"psychology\", \"label\": \"مدیریت اضطراب\", \"value\": \"کاهش استرس امتحان\"}, {\"icon\": \"trending_up\", \"label\": \"کوچینگ عملکرد\", \"value\": \"پایش هفتگی نمرات\"}]}}, {\"id\": \"symptoms-mryr2rs0-xf3s2f\", \"type\": \"symptoms\", \"props\": {\"items\": [{\"desc\": \"شناسایی دقیق هوش‌های چندگانه، رغبت‌های شغلی و تحلیل آینده بازار کار رشته‌ها.\", \"icon\": \"explore\", \"title\": \"استعدادیابی و انتخاب رشته (نهم و کنکور)\"}, {\"desc\": \"تدوین برنامه مطالعاتی روزانه و هفتگی متناسب با سبک یادگیری و ساعت زیستی داوطلب.\", \"icon\": \"calendar_month\", \"title\": \"برنامه‌ریزی مطالعاتی اختصاصی\"}, {\"desc\": \"تکنیک‌های علمی غلبه بر حواس‌پرتی، افت تمرکز و فوبیا یا استرس شدید روز آزمون.\", \"icon\": \"assignment_turned_in\", \"title\": \"مدیریت اضطراب امتحان و کنکور\"}, {\"desc\": \"تحلیل فرسودگی شغلی، انتخاب شغل دوم یا مهاجرت شغلی بر اساس تیپ شخصیتی.\", \"icon\": \"badge\", \"title\": \"تغییر مسیر شغلی بزرگسالان\"}, {\"desc\": \"افزایش سرعت مطالعه، خلاصه‌نویسی حرفه‌ای و مهارتهای مرور فعال دانش‌آموزان.\", \"icon\": \"timer\", \"title\": \"آموزش مهارتهای تست‌زنی و مدیریت زمان\"}, {\"desc\": \"رهایی از ناامیدی تحصیلی و بازسازی اعتمادبه‌نفس پس از نتایج نامطلوب آزمون‌ها.\", \"icon\": \"psychology_alt\", \"title\": \"افزایش انگیزه و خودباوری\"}], \"title\": \"خدمات مشاوره تحصیلی و شغلی شامل چه مواردی است؟\", \"subtitle\": \"پاسخ به مهم‌ترین تصمیمات سرنوشت‌ساز زندگی در مقاطع حساس:\"}}, {\"id\": \"process-mryr2rs0-5ror86\", \"type\": \"process\", \"props\": {\"steps\": [{\"desc\": \"اجرای آزمون‌های معتبر هالند (Holland)، شخصیت شغلی MBTI و هوش‌های چندگانه گاردنر.\", \"title\": \"اجرای پکیج تست‌های استعدادیابی\", \"number\": \"۰۱\"}, {\"desc\": \"ارائه گزارش جامع چاپی و تحلیل نقاط قوت و زمینه‌های رشد توسط مشاور ارشد.\", \"title\": \"تحلیل دقیق نمودارهای استعداد\", \"number\": \"۰۲\"}, {\"desc\": \"تنظیم برنامه کاملاً شخصی‌سازی شده بر اساس ساعت توان و اهداف شفاف.\", \"title\": \"تدوین برنامه مطالعاتی / شغلی\", \"number\": \"۰۳\"}, {\"desc\": \"پیگیری بازدهی هفته به هفته و اصلاح برنامه بر اساس بازخورد آزمون‌های آزمایشی.\", \"title\": \"پشتیبانی و پیگیری مستمر\", \"number\": \"۰۴\"}], \"title\": \"مراحل مشاوره و درمان در کلینیک ژینو\", \"eyebrow\": \"فرآیند دریافت خدمت\"}}, {\"id\": \"features-mryr2rs0-s29y5h\", \"type\": \"features\", \"props\": {\"items\": [{\"desc\": \"ارائه پرونده ۳۰ صفحه‌ای از تحلیل نموداری استعدادها و مشاغل پیشنهادی متناسب.\", \"icon\": \"analytics\", \"title\": \"گزارش تحلیلی جامع نرم‌افزاری\"}, {\"desc\": \"بهره‌گیری از اساتید دانشگاه و رتبه‌های برتر کنکور با سابقه رتبه‌پروری متوالی.\", \"icon\": \"person_check\", \"title\": \"مشاوران متخصص با سابقه درخشان\"}, {\"desc\": \"توجیه والدین جهت ایجاد محیطی آرام و بدون فشار در منزل برای یادگیری فرزند.\", \"icon\": \"family_star\", \"title\": \"همراهی با خانواده\"}, {\"desc\": \"امکان چک کردن گزارش کار مطالعاتی روزانه داوطلب از طریق پیام‌رسان‌ها.\", \"icon\": \"laptop_chromebook\", \"title\": \"پشتیبانی آنلاین تحصیلی\"}], \"title\": \"چرا مشاوره تحصیلی و شغلی ژینو متفاوت است؟\"}}, {\"id\": \"doctors-mryr2rs0-twlsjs\", \"type\": \"doctors\", \"props\": {\"title\": \"روانشناسان و درمانگران این خدمت\", \"maxCount\": 3, \"subtitle\": \"متخصصین دارای پروانه نظام روانشناسی و حداقل ۸ سال سابقه تخصصی\", \"specialtiesFilter\": [\"career\"]}}, {\"id\": \"testimonials-mryr2rs1-bi7viz\", \"type\": \"testimonials\", \"props\": {\"items\": [{\"name\": \"شایان م. (رتبه ۴۲ کنکور تجربی)\", \"role\": \"دانش‌آموز مراجع مشاوره تحصیلی\", \"rating\": 5, \"comment\": \"برنامه‌ریزی دقیق خانم همایونیان و کنترل استرس‌های سال کنکور عالی بود. بدون برنامه‌های ایشان این رتبه ممکن نبود.\"}, {\"name\": \"الهام پ.\", \"role\": \"مراجع مشاوره هدایت شغلی\", \"rating\": 5, \"comment\": \"بعد از ۱۰ سال کار کارمندی احساس پوچی داشتم. تست‌های استعدادیابی کلینیک ژینو مسیر شغلی جدیدی به من نشان داد که عاشقش هستم.\"}], \"title\": \"نظرات و تجربیات مراجعین این خدمت\", \"subtitle\": \"بازخورد واقعی مراجعین کلینیک روانشناسی ژینو\"}}, {\"id\": \"faqs-mryr2rs1-gjlhse\", \"type\": \"faqs\", \"props\": {\"items\": [{\"answer\": \"استعدادیابی از سنین ۱۲ سالگی امکان‌پذیر است اما دوره نهایی انتخاب رشته در پایه نهم و سال‌های دبیرستان بیشترین اهمیت را دارد.\", \"question\": \"بهترین زمان برای استعدادیابی تحصیلی چه سنی است؟\"}], \"title\": \"سوالات متداول درباره این خدمت\", \"subtitle\": \"پاسخ شفاف به ابهامات متداول شما\"}}, {\"id\": \"other-mryr2rs1-wwxttk\", \"type\": \"otherServices\", \"props\": {\"title\": \"مشاهده سایر خدمات و دپارتمان‌های کلینیک ژینو\"}}, {\"id\": \"cta-mryr2rs1-48jp30\", \"type\": \"cta\", \"props\": {\"badge\": \"گام اول به سوی سلامت و آرامش روانی\", \"title\": \"همین امروز نوبت مشاوره خود را رزرو کنید\", \"subtitle\": \"فرآیند رزرو نوبت کمتر از ۲ دقیقه زمان می‌برد. امکان دریافت نوبت‌های حضوری در مطب یا مشاوره ویدیویی آنلاین موجود است.\", \"phoneHref\": \"tel:02188776655\", \"phoneLabel\": \"تماس با پذیرش (۰۲۱-۸۸۷۷۶۶۵۵)\"}}], \"version\": 1}, \"targetScreen\": \"services\"}', '2026-07-24 09:41:02'),
('adult-individual', '{\"id\": \"adult-individual\", \"icon\": \"person\", \"title\": \"مشاوره فردی بزرگسال\", \"format\": \"حضوری و آنلاین\", \"bgClass\": \"bg-surface-container-low\", \"duration\": \"۴۵ دقیقه\", \"description\": \"درمان تخصصی اضطراب، افسردگی، وسواس و چالش‌های زندگی شخصی با رویکردهای مدرن روانشناختی برای دستیابی به تعادل روانی پایدار.\", \"pageBuilder\": {\"blocks\": [{\"id\": \"hero-mryr2rs8-onokme\", \"type\": \"hero\", \"props\": {\"badge\": \"دپارتمان تخصصی روان‌درمانی\", \"title\": \"مشاوره فردی بزرگسال\", \"format\": \"حضوری در کلینیک & آنلاین سراسر کشور\", \"duration\": \"۴۵ دقیقه هر جلسه\", \"subtitle\": \"مسیر تخصصی رهایی از اضطراب، افسردگی و دست‌یابی به آرامش پایدار درونی با رویکردهای CBT و طرحواره درمانی\", \"heroImage\": \"https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&q=80&w=1000\", \"sessionFeeNote\": \"امکان دریافت معرفی‌نامه بیمه تکمیلی\", \"satisfactionRate\": \"۹۸٪ رضایت مراجعین\"}}, {\"id\": \"highlights-mryr2rs8-rgna0s\", \"type\": \"highlights\", \"props\": {\"items\": [{\"icon\": \"schedule\", \"label\": \"مدت زمان هر جلسه\", \"value\": \"۴۵ دقیقه\"}, {\"icon\": \"videocam\", \"label\": \"شیوه برگزاری\", \"value\": \"حضوری / آنلاین\"}, {\"icon\": \"workspace_premium\", \"label\": \"رویکرد درمانی\", \"value\": \"CBT, ACT, طرحواره\"}, {\"icon\": \"verified_user\", \"label\": \"ضمانت محرمانگی\", \"value\": \"۱۰۰٪ کدهای اخلاقی\"}]}}, {\"id\": \"symptoms-mryr2rs8-hwp76v\", \"type\": \"symptoms\", \"props\": {\"items\": [{\"desc\": \"اشتغال ذهنی مداوم با نگرانی‌های آینده، دلشوره بی‌دلیل، و احساس عدم امنیت در تصمیم‌گیری‌ها.\", \"icon\": \"psychology\", \"title\": \"استرس و اضطراب مزمن\"}, {\"desc\": \"افت انرژی حیاتی، احساس خستگی مداوم، بی‌علاقگی به فعالیت‌های مورد علاقه و حس بن‌بست.\", \"icon\": \"sentiment_dissatisfied\", \"title\": \"افسردگی و بی‌انگیزگی\"}, {\"desc\": \"افکار تکرارشونده مزاحم و رفتارهای اجباری که زمان و انرژی زیادی را از روزمره شما تلف می‌کنند.\", \"icon\": \"published_with_changes\", \"title\": \"وسواس فکری و عملی (OCD)\"}, {\"desc\": \"چالش در گذر از تجربه جدایی یا از دست دادن عزیزان و بازسازی عزت‌نفس تخریب‌شده.\", \"icon\": \"heart_broken\", \"title\": \"سوگ و شکست عاطفی\"}, {\"desc\": \"عدم شناخت نیازهای واقعی خود، احساس پوچی در مسیر شغلی و شخصی، و عدم قدرت نه گفتن.\", \"icon\": \"person_search\", \"title\": \"سردرگمی و بحران هویت\"}, {\"desc\": \"عدم توانایی در مدیریت خشم، واکنش‌های هیجانی ناگهانی و آسیب به روابط نزدیک.\", \"icon\": \"mood_bad\", \"title\": \"نوسانات خلقی و پرخاشگری\"}], \"title\": \"چه زمانی مراجعه به مشاوره فردی ضرورت می‌یابد؟\", \"subtitle\": \"اگر با یک یا چند مورد از چالش‌های زیر مواجه هستید، جلسات فردی بهترین گام برای بازسازی کیفیت زندگی شماست:\"}}, {\"id\": \"process-mryr2rs8-qqeye3\", \"type\": \"process\", \"props\": {\"steps\": [{\"desc\": \"بررسی دقیق سوابق، ریشه‌یابی مشکلات اصلی و اجرای پرسشنامه‌های روان‌سنجی اولیه.\", \"title\": \"مصاحبه تشخیصی اولیه\", \"number\": \"۰۱\"}, {\"desc\": \"تعیین اهداف شفاف و انتخاب مناسب‌ترین رویکرد علمی (شناختی-رفتاری، پذیرش و تعهد، یا طرحواره درمانی).\", \"title\": \"تدوین نقشه راه درمان (Treatment Plan)\", \"number\": \"۰۲\"}, {\"desc\": \"انجام تمرینات تخصصی در جلسه، بازسازی خطاهای شناختی و یادگیری مهارتهای عملی مدیریت هیجان.\", \"title\": \"جلسات منظم روان‌درمانی\", \"number\": \"۰۳\"}, {\"desc\": \"سنجش تغییرات مثبت با تست‌های مجدد و آماده‌سازی برای استقلال پایدار فرد از درمانگر.\", \"title\": \"پایش پیشرفت و تثبیت نتایج\", \"number\": \"۰۴\"}], \"title\": \"مراحل مشاوره و درمان در کلینیک ژینو\", \"eyebrow\": \"فرآیند دریافت خدمت\"}}, {\"id\": \"features-mryr2rs8-3icb1p\", \"type\": \"features\", \"props\": {\"items\": [{\"desc\": \"استفاده از پروتکل‌های درمانی استاندارد CBT, ACT و ERP منطبق بر جدیدترین یافته‌های انجمن روانشناسی آمریکا (APA).\", \"icon\": \"psychology_alt\", \"title\": \"به‌روزترین رویکردهای تخصصی\"}, {\"desc\": \"تمام گفتگوها و پرونده‌های مراجعین مطابق با بالاترین استانداردهای اخلاقی و رازداری روان‌درمانی محافظت می‌شود.\", \"icon\": \"lock\", \"title\": \"حفظ مطلق حریم خصوصی\"}, {\"desc\": \"فضای فیزیکی کلینیک جهت کاهش استرس و ایجاد حس امنیت کاملاً اکوستیک و ارگونومیک طراحی شده است.\", \"icon\": \"nature_people\", \"title\": \"محیط ارامش‌بخش و استاندارد\"}, {\"desc\": \"ارائه خدمت توسط متخصصان دارای پروانه اشتغال تخصصی از سازمان نظام روانشناسی و مشاوره کشور.\", \"icon\": \"groups\", \"title\": \"کادر درمانگران ارشد\"}], \"title\": \"مزایای خدمات مشاوره فردی در کلینیک ژینو\"}}, {\"id\": \"doctors-mryr2rs8-jquppg\", \"type\": \"doctors\", \"props\": {\"title\": \"روانشناسان و درمانگران این خدمت\", \"maxCount\": 3, \"subtitle\": \"متخصصین دارای پروانه نظام روانشناسی و حداقل ۸ سال سابقه تخصصی\", \"specialtiesFilter\": [\"individual\", \"cbt\"]}}, {\"id\": \"testimonials-mryr2rs8-fxt0bs\", \"type\": \"testimonials\", \"props\": {\"items\": [{\"name\": \"مریم ک.\", \"role\": \"مراجع مشاوره فردی (درمان اضطراب)\", \"rating\": 5, \"comment\": \"بعد از ۶ جلسه مشاوره با خانم دیهیمی، حملات پانیک من به‌طور کامل کنترل شد و توانستم دوباره با خیال راحت به محیط کارم برگردم.\"}, {\"name\": \"رضا م.\", \"role\": \"مراجع روان‌درمانی (وسواس فکری)\", \"rating\": 5, \"comment\": \"تمرینات ERP و رویکرد علمی کلینیک ژینو دید من نسبت به وسواس را تغییر داد. فوق‌العاده سپاسگزارم.\"}], \"title\": \"نظرات و تجربیات مراجعین این خدمت\", \"subtitle\": \"بازخورد واقعی مراجعین کلینیک روانشناسی ژینو\"}}, {\"id\": \"faqs-mryr2rs8-4el4zk\", \"type\": \"faqs\", \"props\": {\"items\": [{\"answer\": \"تعداد جلسات بستگی به شدت مشکل و نوع رویکرد درمانی دارد. معمولاً دوره‌های کوتاه‌مدت بین ۸ تا ۱۵ جلسه و دوره‌های عمیق‌تر بیشتر طول می‌کشند.\", \"question\": \"چند جلسه مشاوره فردی برای گرفتن نتیجه لازم است؟\"}, {\"answer\": \"بله، تمامی جلسات مشاوره فردی با همان کیفیت حضوری از طریق بستر ویدیویی امن و اختصاصی برگزار می‌گردد.\", \"question\": \"آیا امکان برگزاری جلسه به صورت آنلاین وجود دارد؟\"}, {\"answer\": \"روانشناس با گفتاردرمانی، تکنیک‌های شناختی و رفتاردرمانی به حل مشکلات می‌پردازد؛ در حالی که روانپزشک در صورت نیاز دارو تجویز می‌کند.\", \"question\": \"تفاوت روانشناس و روانپزشک چیست؟\"}], \"title\": \"سوالات متداول درباره این خدمت\", \"subtitle\": \"پاسخ شفاف به ابهامات متداول شما\"}}, {\"id\": \"other-mryr2rs8-qws1gd\", \"type\": \"otherServices\", \"props\": {\"title\": \"مشاهده سایر خدمات و دپارتمان‌های کلینیک ژینو\"}}, {\"id\": \"cta-mryr2rs8-ot9rbz\", \"type\": \"cta\", \"props\": {\"badge\": \"گام اول به سوی سلامت و آرامش روانی\", \"title\": \"همین امروز نوبت مشاوره خود را رزرو کنید\", \"subtitle\": \"فرآیند رزرو نوبت کمتر از ۲ دقیقه زمان می‌برد. امکان دریافت نوبت‌های حضوری در مطب یا مشاوره ویدیویی آنلاین موجود است.\", \"phoneHref\": \"tel:02188776655\", \"phoneLabel\": \"تماس با پذیرش (۰۲۱-۸۸۷۷۶۶۵۵)\"}}], \"version\": 1}, \"targetScreen\": \"adult-therapy\"}', '2026-07-24 09:41:02'),
('child-play-therapy', '{\"id\": \"child-play-therapy\", \"icon\": \"child_care\", \"title\": \"کودک و نوجوان (بازی درمانی)\", \"bgClass\": \"bg-primary-fixed text-on-primary-fixed\", \"duration\": \"۳ تا ۱۸ سال\", \"description\": \"ارزیابی و درمان اختلالات رفتاری، اضطراب جدایی، بیش‌فعالی و پرخاشگری با استفاده از متدهای علمی بازی‌درمانی.\", \"pageBuilder\": {\"blocks\": [{\"id\": \"hero-mryr2rsj-rkhep7\", \"type\": \"hero\", \"props\": {\"badge\": \"اتاق بازی استاندارد و روانسنجی کودک\", \"title\": \"کودک و نوجوان (بازی درمانی تخصصی)\", \"format\": \"بازی‌درمانی حضوری + مشاوره والدین\", \"duration\": \"۴۵ دقیقه\", \"subtitle\": \"تشخیص و درمان اختلالات رفتاری، اضطراب جدایی، بیش‌فعالی و پرخاشگری در اتاق بازی مجهز روانشناختی\", \"heroImage\": \"https://images.unsplash.com/photo-1485546246426-74dc88dec4d9?auto=format&fit=crop&q=80&w=1000\", \"sessionFeeNote\": \"همراه با جلسات آموزش فرزندپروری به والدین\", \"satisfactionRate\": \"۹۸٪ رضایت والدین\"}}, {\"id\": \"highlights-mryr2rsj-txzpgf\", \"type\": \"highlights\", \"props\": {\"items\": [{\"icon\": \"child_care\", \"label\": \"رده سنی\", \"value\": \"۳ تا ۱۸ سال\"}, {\"icon\": \"toys\", \"label\": \"محیط درمان\", \"value\": \"اتاق بازی شن و ابزار\"}, {\"icon\": \"supervisor_account\", \"label\": \"جلسات موازی\", \"value\": \"کودک + آموزش والدین\"}, {\"icon\": \"psychology\", \"label\": \"تست‌های کودک\", \"value\": \"هوش، ADHD، استعداد\"}]}}, {\"id\": \"symptoms-mryr2rsj-fbvjsi\", \"type\": \"symptoms\", \"props\": {\"items\": [{\"desc\": \"گریه شدید هنگام جدا شدن از والدین، کابوس‌های شبانه و عدم تمایل به رفتن به مهد یا مدرسه.\", \"icon\": \"sentiment_very_dissatisfied\", \"title\": \"اضطراب جدایی و ترس از مدرسه\"}, {\"desc\": \"بی‌قراری مداوم، عدم توانایی در نشستن، حواس‌پرتی شدید در تکالیف و رفتارهای تکانه‌ای.\", \"icon\": \"bolt\", \"title\": \"بیش‌فعالی و نقص توجه (ADHD)\"}, {\"desc\": \"جیغ زدن، پرتاب وسایل، لجبازی شدید و عدم اطاعت از قوانین ساده خانه.\", \"icon\": \"warning\", \"title\": \"پرخاشگری و قشقرق‌های رفتاری\"}, {\"desc\": \"واکنش‌های جسمانی ناشایست به استرس‌های پنهان خانوادگی یا تولد فرزند جدید.\", \"icon\": \"bedroom_baby\", \"title\": \"شب‌ادراری و ناخن‌جویدن\"}, {\"desc\": \"افت ناگهانی نمرات، گوشه‌گیری نوجوان، افت اعتماد به نفس و چالش‌های دوره بلوغ.\", \"icon\": \"escalator_warning\", \"title\": \"افت تحصیلی و چالش‌های نوجوان\"}, {\"desc\": \"انزوای اجتماعی کودک و وابستگی شدید به صفحه‌نمایش‌ها همراه با افت مهارت‌های ارتباطی.\", \"icon\": \"smart_toy\", \"title\": \"اعتیاد به بازی‌های کامپیوتر و موبایل\"}], \"title\": \"چه نشانه‌هایی در کودک نیازمند ارزیابی روانشناس است؟\", \"subtitle\": \"کودکان زبان بیان مستقیم هیجانات را ندارند؛ رفتار آن‌ها زبان درون آن‌هاست:\"}}, {\"id\": \"process-mryr2rsj-1oowgc\", \"type\": \"process\", \"props\": {\"steps\": [{\"desc\": \"اخذ شرح حال کامل، تاریخچه رشدی کودک و شناسایی نگرانی‌های اصلی والدین.\", \"title\": \"مصاحبه اول با والدین (بدون حضور کودک)\", \"number\": \"۰۱\"}, {\"desc\": \"ورود کودک به اتاق بازی مجهز و مشاهده تعاملات، الگوهای بازی و ناخودآگاه او.\", \"title\": \"جلسات ارزیابی و بازی‌درمانی کودک\", \"number\": \"۰۲\"}, {\"desc\": \"اجرای تست‌های هوش وکسلر، سنجش تمرکز نکسوس و ارزیابی رفتاری کودک.\", \"title\": \"اجرای تست‌های تخصصی (در صورت نیاز)\", \"number\": \"۰۳\"}, {\"desc\": \"ارائه راهکارهای عملی به والدین جهت اصلاح رفتار در منزل و تثبیت درمان.\", \"title\": \"جلسه بازخورد و کارگاه فرزندپروری\", \"number\": \"۰۴\"}], \"title\": \"مراحل مشاوره و درمان در کلینیک ژینو\", \"eyebrow\": \"فرآیند دریافت خدمت\"}}, {\"id\": \"features-mryr2rsj-ooxmxr\", \"type\": \"features\", \"props\": {\"items\": [{\"desc\": \"ابزار قدرتمند درمانی برای ابراز غیرکلامی تروماها و هیجانات سرکوب‌شده کودک.\", \"icon\": \"water_drop\", \"title\": \"میز شن‌بازی تخصصی (Sand Therapy)\"}, {\"desc\": \"وسایل سفال‌گری، رنگ‌آمیزی و ساخت کاردستی جهت تخلیه هیجان و افزایش تمرکز.\", \"icon\": \"palette\", \"title\": \"بخش هنردرمانی و نقاشی\"}, {\"desc\": \"امکان مشاهده رفتارهای طبیعی کودک توسط درمانگر ارشد بدون ایجاد حس مراقبت در کودک.\", \"icon\