('coaching-development', '{\"id\": \"coaching-development\", \"icon\": \"workspace_premium\", \"badge\": \"جامع‌ترین خدمات\", \"title\": \"توسعه فردی و کوچینگ\", \"bgClass\": \"bg-surface-container-lowest border border-outline-variant\", \"description\": \"برنامه‌های مدون برای افزایش اعتماد به نفس، مدیریت زمان، تاب‌آوری و بهبود مهارت‌های نرم زندگی.\", \"pageBuilder\": {\"blocks\": [{\"id\": \"hero-mryr2rsu-gffk1o\", \"type\": \"hero\", \"props\": {\"badge\": \"جامع‌ترین برنامه رشد و موفقیت شخصی\", \"title\": \"توسعه فردی، کوچینگ و مهارت‌های زندگی\", \"format\": \"حضوری & آنلاین (دوره ۵ یا ۱۰ جلسه‌ای)\", \"duration\": \"۵۰ دقیقه\", \"subtitle\": \"افزایش اعتمادبه‌نفس، مدیریت زمان، پایداری در اهداف، مهارت نه گفتن و ارتقای کیفیت زندگی شخصی و کاری\", \"heroImage\": \"https://images.unsplash.com/photo-1517048676732-d65bc937f952?auto=format&fit=crop&q=80&w=1000\", \"sessionFeeNote\": \"همراه با چک‌لیست‌های روزانه و ارزیابی لایف‌استایل\", \"satisfactionRate\": \"۹۹٪ تحقق اهداف فردی\"}}, {\"id\": \"highlights-mryr2rsu-ad0nh4\", \"type\": \"highlights\", \"props\": {\"items\": [{\"icon\": \"workspace_premium\", \"label\": \"کوچینگ حرفه‌ای\", \"value\": \"برنامه اختصاصی ۵ جلسه‌ای\"}, {\"icon\": \"auto_graph\", \"label\": \"افزایش عملکرد\", \"value\": \"رشد ۲ برابری بازدهی\"}, {\"icon\": \"military_tech\", \"label\": \"اعتماد به نفس\", \"value\": \"تقویت عزت‌نفس و سرسختی\"}, {\"icon\": \"checklist\", \"label\": \"ارزیابی مداوم\", \"value\": \"پیگیری تمرینات هفته\"}]}}, {\"id\": \"symptoms-mryr2rsu-m7gkx3\", \"type\": \"symptoms\", \"props\": {\"items\": [{\"desc\": \"احساس عدم شایستگی در جمع، خودانتقادی شدید و ترس از صحبت کردن یا ابراز وجود.\", \"icon\": \"self_improvement\", \"title\": \"کمبود شدید اعتمادبه‌نفس و عزت‌نفس\"}, {\"desc\": \"به تعویق انداختن مداوم کارهای مهم، اهمال‌کاری و احساس گناه پس از هدر رفتن زمان.\", \"icon\": \"schedule_send\", \"title\": \"امروز و فردا کردن (تکاهل و اهمال‌کاری)\"}, {\"desc\": \"سختی در مرزبندی شخصی، فدا کردن اولویت‌های خود برای خشنود ساخت