('couples-marriage', '{\"id\": \"couples-marriage\", \"icon\": \"favorite\", \"badge\": \"تخصصی\", \"title\": \"زوج‌درمانی و پیش از ازدواج\", \"bgClass\": \"bg-surface-container-highest\", \"duration\": \"۶۰ دقیقه\", \"description\": \"بهبود روابط عاطفی، حل تعارضات زناشویی و اتخاذ تصمیمات آگاهانه بر اساس تست‌های تخصصی برای شروع زندگی مشترک.\", \"pageBuilder\": {\"blocks\": [{\"id\": \"hero-mryr2rt2-ga1xy7\", \"type\": \"hero\", \"props\": {\"badge\": \"دپارتمان تخصصی خانواده و ازدواج\", \"title\": \"زوج‌درمانی و مشاوره پیش از ازدواج\", \"format\": \"جلسات دونفره حضوری و آنلاین\", \"duration\": \"۶۰ الی ۹۰ دقیقه\", \"subtitle\": \"حل تعارضات زناشویی، بازسازی صمیمیت عاطفی و اتخاذ تصمیمات آگاهانه بر اساس متدهای علمی گاتمن و EFT\", \"heroImage\": \"https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&q=80&w=1000\", \"sessionFeeNote\": \"همراه با تحلیل تست‌های تخصصی سنخ شخصیتی\", \"satisfactionRate\": \"۹۷٪ بهبود روابط زوجین\"}}, {\"id\": \"highlights-mryr2rt2-i5x3kk\", \"type\": \"highlights\", \"props\": {\"items\": [{\"icon\": \"favorite\", \"label\": \"رویکرد علمی\", \"value\": \"متد زوج‌درمانی گاتمن\"}, {\"icon\": \"group\", \"label\": \"نوع جلسه\", \"value\": \"دونفره + جلسات فردی\"}, {\"icon\": \"fact_check\", \"label\": \"تست‌های مکمل\", \"value\": \"ارزیابی NEO و مشاوره\"}, {\"icon\": \"handshake\", \"label\": \"هدف درمانی\", \"value\": \"حل تعارض & صمیمیت\"}]}}, {\"id\": \"symptoms-mryr2rt2-jfl73p\", \"type\": \"symptoms\", \"props\": {\"items\": [{\"desc\": \"وقتی گفتگوها سریعاً به دعوا، قهر، طعنه یا سکوت سنگین منتهی می‌شوند.\", \"icon\": \"forum\", \"title\": \"بحث‌های تکراری و بی‌نتیجه\"}, {\"desc\": \"احساس فاصله گرفتن از یکدیگر، سردی روابط و احساس تنهایی در کنار همسر.\", \"icon\": \"heart_minus\", \"title\": \"کاهش صمیمیت عاطفی و زناشویی\"}, {\"desc\": \"ارزیابی همسانی شخصیتی، بررسی خط قرمزها و میزان آمادگی هر دو طرف برای شروع زندگی.\", \"icon\": \"psychology\", \"title\": \"مشاوره پیش از ازدواج (Pre-marital)\"}, {\"desc\": \"پروتکل تخصصی بازسازی اعتماد پس از آسیب‌های عاطفی و خیانت زناشویی.\", \"icon\": \"gavel\", \"title\": \"خیانت و آسیب به اعتماد\"}, {\"desc\": \"عدم مرزبندی صحیح با خانواده همسر و ایجاد تنش در تصمیم‌گیری‌های مستقل زوج.\", \"icon\": \"family_restroom\", \"title\": \"دخالت اطرافیان و خانواده‌ها\"}, {\"desc\": \"عدم توافق زوجین بر سر نحوه مواجهه با رفتارهای فرزندان و قوانین خانه.\", \"icon\": \"escalator_warning\", \"title\": \"تربیت فرزند و اختلاف در روش‌ها\"}], \"title\": \"چه زمانی زوجین نیازمند مشاوره تخصصی هستند؟\", \"subtitle\": \"اگر در رابطه عاطفی یا مسیر ازدواج خود با موقعیت‌های زیر مواجه‌اید:\"}}, {\"id\": \"process-mryr2rt2-073vzx\", \"type\": \"process\", \"props\": {\"steps\": [{\"desc\": \"شنیدن دغدغه‌های هر دو طرف در فضایی کاملاً بی‌طرفانه و بدون قضاوت.\", \"title\": \"جلسه ارزیابی مشترک اول\", \"number\": \"۰۱\"}, {\"desc\": \"یک جلسه جداگانه برای هر یک از زوجین جهت بررسی طرحواره‌ها و تست‌های شخصیتی.\", \"title\": \"جلسات تک‌نفره و تست‌های تخصصی\", \"number\": \"۰۲\"}, {\"desc\": \"تبیین نقاط قوت و «چهار سوار سرنوشت ساز» رابطه بر اساس فرمول استاندارد گاتمن.\", \"title\": \"ارائه تحلیل الگوهای رابطه\", \"number\": \"۰۳\"}, {\"desc\": \"آموزش مهارت گوش دادن فعال، مدیریت خشم در بحث و بازسازی پیوند عاطفی.\", \"title\": \"تمرینات عملی گفتگو و صمیمیت\", \"number\": \"۰۴\"}], \"title\": \"مراحل مشاوره و درمان در کلینیک ژینو\", \"eyebrow\": \"فرآیند دریافت خدمت\"}}, {\"id\": \"features-mryr2rt2-zrh5mr\", \"type\": \"features\", \"props\": {\"items\": [{\"desc\": \"درمانگران ما هرگز جانبداری نکرده و به عنوان تسهیل‌گر منصف برای نجات رابطه تلاش می‌کنند.\", \"icon\": \"balance\", \"title\": \"بی‌طرفی کامل درمانگر\"}, {\"desc\": \"به‌کارگیری پرسشنامه‌ها و چک‌لیست‌های معتبر جهانی برای سنجش میزان سلامت رابطه.\", \"icon\": \"menu_book\", \"title\": \"پروتکل استاندارد انستیتو گاتمن\"}, {\"desc\": \"کمک به زوجین برای اخذ منطقی‌ترین تصمیم در شرایط بحرانی با حداقل آسیب به فرزندان.\", \"icon\": \"diversity_1\", \"title\": \"مشاوره پیش از طلاق و تصمیم‌گیری\"}, {\"desc\": \"بهره